# Punto 5: envio automatico del resumen al cliente. Uso: python3 install5.py
import os,re,shutil,subprocess,sys,base64
API='/var/www/vibkaptur/public/api'; PRIV='/var/www/vibkaptur/private'
F={'vk_comun.php':(PRIV,''),'destinatarios.php':(API,''),'resumen.php':(API,'')}
try: os.remove('/var/www/vibkaptur/public/t_5m8w2r6k1v.txt')
except Exception: pass
m=re.search(r"\$KEY\s*=\s*'([^']+)'",open(os.path.join(API,'aviso.php'),encoding='utf-8').read())
if not m: print('FALLO: no encuentro la clave de Brevo en aviso.php. NO SE HA TOCADO NADA'); sys.exit(1)
for n,(d,c) in F.items():
    open('/tmp/_'+n,'wb').write(base64.b64decode(c))
    if subprocess.run(['php','-l','/tmp/_'+n],capture_output=True).returncode!=0: print('FALLO de sintaxis en',n,'. NO SE HA TOCADO NADA'); sys.exit(1)
ru=os.stat(os.path.join(PRIV,'users.php')); ra=os.stat(os.path.join(API,'clave.php'))
def put(path,data,ref,mode=None):
    open(path,'wb').write(data); os.chown(path,ref.st_uid,ref.st_gid); os.chmod(path,mode if mode else ref.st_mode&0o7777)
put(os.path.join(PRIV,'brevo.key'),m.group(1).encode(),ru,0o640 if (ru.st_mode&0o004)==0 else None)
for n in ('destinatarios.json','envios.log'):
    fp=os.path.join(PRIV,n)
    if not os.path.exists(fp): put(fp,b'{}' if n.endswith('json') else b'',ru)
for n,(d,c) in F.items(): put(os.path.join(d,n),base64.b64decode(c),ru if d==PRIV else ra)
# comprobar que el servidor web puede leer la clave y escribir la lista
import pwd
u=pwd.getpwuid(ra.st_uid).pw_name
print('archivos de', pwd.getpwuid(ru.st_uid).pw_name, '/ api de', u)
print('ENVIO AL CLIENTE INSTALADO (apagado en todos los clientes hasta que lo actives)')
